-- Explicit development seed: 60 deterministic jobs modeled after src/data/mock-jobs.ts.
-- Run once after the Phase 2 migration. Re-running is safe because (source, external_id) is unique.
with seed as (select i, (array['Software Engineering Intern','Frontend Engineering Intern','Full Stack Developer Intern','Graphics Software Intern','Game Engineering Intern','Web Developer Intern','Robotics Software Intern','Machine Learning Intern'])[1+(i-1)%8] title, (array['Software Engineering','Frontend','Full Stack','Graphics','Game Development','Web Development','Robotics','Machine Learning'])[1+(i-1)%8] category, (array['HubSpot','Klaviyo','iRobot','MathWorks','Wayfair','DraftKings','Autodesk','Unity','NVIDIA','Boston Dynamics'])[1+(i*5)%10] company, (array['Boston, MA','Cambridge, MA','Worcester, MA','Remote US','New York, NY','Providence, RI','San Francisco, CA','Seattle, WA'])[1+(i*3)%8] location from generate_series(1,60) i)
insert into public.jobs(external_id,source,source_url,application_url,company,title,description,location,workplace_type,employment_type,salary_min,salary_max,salary_currency,skills,seniority,sponsorship,posted_at,discovered_at,content_hash,raw_payload)
select 'mock-'||(10000+i), (array['Greenhouse','Lever','Ashby'])[1+(i-1)%3], 'https://example.com/jobs', 'https://example.com/jobs/'||i, company,title, company||' is looking for a curious, collaborative '||lower(title)||' to ship thoughtful software. You will build production features, investigate technical problems, document decisions, and collaborate with engineers and designers. Coursework, projects, open source, and prior internships are welcome.',location,(array['hybrid','remote','onsite'])[1+(i*2)%3],(array['internship','internship','internship','part-time','full-time','contract'])[1+(i-1)%6],24+(i%9),35+(i%14),'USD',array[(array['TypeScript','React','Next.js','JavaScript','Python','C++','Node.js','Git'])[1+(i-1)%8],(array['React','Next.js','JavaScript','Python','C++','Node.js','Git','PostgreSQL'])[1+(i-1)%8]],'student',(i%4<>0),timestamptz '2026-08-28 12:00:00+00'-((i*7)%45)*interval '1 day',timestamptz '2026-08-28 12:00:00+00'-((i*3)%18)*interval '1 day',encode(digest('mock-job-'||i,'sha256'),'hex'),jsonb_build_object('category',category,'evaluation',jsonb_build_object('overallScore',60+((i*17+29)%38),'skillScore',65+((i*7)%34),'experienceScore',60+((i*5)%35),'interestScore',70+((i*3)%29),'locationScore',case when location='Remote US' then 98 else 82 end,'educationScore',94,'companyScore',68+(i%28),'compensationScore',65+(i%31),'verdict',case when 60+((i*17+29)%38)>=90 then 'excellent' when 60+((i*17+29)%38)>=80 then 'strong' when 60+((i*17+29)%38)>=70 then 'possible' else 'weak' end,'recommendation',case when 60+((i*17+29)%38)>=82 then 'apply' when 60+((i*17+29)%38)>=70 then 'consider' else 'skip' end,'summary','A deterministic development match for '||title||' at '||company||'.','matchingSkills',to_jsonb(array['TypeScript','React','Git']),'missingSkills',to_jsonb(array['Docker']),'strengths',to_jsonb(array['Student-friendly expectations','Relevant technical overlap']),'concerns',to_jsonb(array['Confirm role details and compensation']),'experienceRequirement','Coursework, projects, or up to 1 year of practical experience')) from seed
on conflict(source,external_id) do nothing;
